import unicodedata

ASK = re.compile(r"\b(?:(?:че|что|чё) говорить|а если спросят|чем заняться|это норм\w*|(?:че|чё|чо) делать|это нормально|что сказать|с чего начать|как (?:правильно )?отказать|как не \w+ти\b|кто (?:\w+ )?(?:платит|заплатит)|как бегать|как (?:бросить|перестать|отвыкнуть)|(?:где|куда) (?:\w+ )?(?:потусить|потусоваться|погулять)|сказать ей|сказать ему|сказать маме|что (?:\w+ )?подаришь|как (?:\w+ )?попросить|что надеть|с чего (?:\w+ )?начн\w*|о ч[её]м (?:лучше )?не говорить|как пережить|как выжить|как (?:бы )?(?:ты )?признал\w*|хочу бросить|стоит,? |куда (?:\w+ )?(?:сводить|сходить|пойти|пригласить)|стоит ли|как не \w+(?:ть|ться)\b|что (?:бы )?(?:\w+ )?подарить|что сказать|как (?:ты )?(?:начн\w*|завяж\w*|познакомишься)|о ч[её]м говорить|посовету\w*|подскаж\w*|совет\w*|как (?:мне |лучше |быстро |правильно |же )?(?:\w+ть|\w+ться|\w+тись)\b|что делать|как быть|что (?:бы )?(?:ты )?(?:посоветовал|делаешь|делал)|помоги)")

